import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  Container,
  Typography,
  Box,
  Grid,
  TextField,
  Button,
  Paper,
  Stepper,
  Step,
  StepLabel,
  Divider,
  Alert
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { useTheme } from '@mui/material/styles';
import { clearCart } from '../features/cartSlice';
import { selectCartItems, selectCartTotal } from '../features/cartSlice';

const CheckoutPage = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const cartItems = useSelector(selectCartItems);
  const total = useSelector(selectCartTotal);
  const [activeStep, setActiveStep] = useState(0);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    address: '',
    city: '',
    country: '',
    zipCode: '',
    cardNumber: '',
    cardName: '',
    expiryDate: '',
    cvv: ''
  });
  const [errors, setErrors] = useState({});

  // Example order summary
  const order = {
    items: [
      { id: 1, name: 'Product A', quantity: 2, price: 10 },
      { id: 2, name: 'Product B', quantity: 1, price: 20 },
    ],
    total: 40,
  };

  return (
    <div className="checkout-container">
      <form className="checkout-form">
        <h2>Shipping Information</h2>
        <label>
          Full Name
          <input type="text" required />
        </label>
        <label>
          Address
          <input type="text" required />
        </label>
        <label>
          City
          <input type="text" required />
        </label>
        <label>
          Postal Code
          <input type="text" required />
        </label>
        <label>
          Country
          <input type="text" required />
        </label>
        <h2>Payment</h2>
        <label>
          Card Number
          <input type="text" required maxLength={16} />
        </label>
        <label>
          Expiry Date
          <input type="text" placeholder="MM/YY" required maxLength={5} />
        </label>
        <label>
          CVC
          <input type="text" required maxLength={3} />
        </label>
        <button type="submit" className="checkout-btn">Place Order</button>
      </form>
      <div className="order-summary">
        <h2>Order Summary</h2>
        <ul>
          {order.items.map(item => (
            <li key={item.id}>
              {item.name} x {item.quantity} = ${item.price * item.quantity}
            </li>
          ))}
        </ul>
        <h3>Total: ${order.total}</h3>
      </div>
    </div>
  );
};

export default CheckoutPage;
